head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07181";
scwin.grd_StkOpt = null;
scwin.chk_PREFSTK_TP_CD = null;
scwin.panel_PREFSTK = null;
scwin.btn_Acpt = null;
scwin.btn_NewList = null;
scwin.panel_pharma_bio_com_yn = null;
scwin.pnl_LIST_INVSTG_COND = null;
scwin.pnl_MAJSHRHD_CONTN = null;
scwin.grd_estiPrfm = null;
scwin.grd_pipeProg = null;
scwin.grid_PubOfrList = null;
scwin.grid_PriOfrList = null;
scwin.grid_AssgnList = null;
scwin.grid_PriOfrAssgnList = null;
scwin.vBzProcsNo = undefined;
scwin.vListProcsStatCd = "";
scwin.isuBzProcsNo = "";
scwin.vListSchdlDd = "";
scwin.vListTpClss = "";
scwin.dts_common_info = null;
scwin.dts_PubOfr = null;
scwin.dts_App = null;
scwin.dts_ShrsList = null;
scwin.dts_LeadComList = null;
scwin.dts_IsuList = null;
scwin.dts_ApplDocList = null;
scwin.dts_Isu = null;
scwin.dts_NEWPREFSTK = null;
scwin.dts_PubOfrList = null;
scwin.dts_AssgnList = null;
scwin.dts_PrtDepoList = null;
scwin.dts_PriOfrList = null;
scwin.dts_PriOfrAssgnList = null;
scwin.dts_StkOptDutyList = null;
scwin.dts_estiPrfm = null;
scwin.dts_pipeProg = null;
scwin.fr_MktId = undefined;
scwin.vToday = undefined;
scwin.fn_common_info = null;
scwin.fn_setLeadCom = null;
scwin.fn_sync_isuDtl = null;
scwin.fn_trs = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.Provider, $c.frame.srcUrl
    try {
        const parentWin = $c.win.getParent();
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        scwin.vListProcsStatCd = parentWin.clickListProcsStatCd;
        scwin.vListSchdlDd = parentWin.clickListSchdlDd;
        scwin.vListTpClss = parentWin.clickListTpClss;
        scwin.setPanelPREFSTK(false);
        scwin.setPREFSTKItem(false);
        scwin.fn_common_info();
        await scwin.syncPub();
        scwin.initForm(scwin.vListProcsStatCd);
        setTimeout(function(){ scwin.setPubOfrGrid(scwin.grid_PubOfrList, scwin.dts_PubOfrList) }, 500);
        setTimeout(function(){ scwin.setAssgnGrid(scwin.grid_AssgnList, scwin.dts_AssgnList) }, 600);
        setTimeout(function(){ scwin.setPriOfrGrid(scwin.grid_PriOfrList, scwin.dts_PriOfrList) }, 500);
        setTimeout(function(){ scwin.setPriOfrAssgnGrid(scwin.grid_PriOfrAssgnList, scwin.dts_PriOfrAssgnList) }, 600);
        await scwin.syncShrs();
        await scwin.syncPrtdepo();
        if (scwin.vListTpClss !== "05") {
            await scwin.syncStkoptduty();
        } else {
            txt_label130.hide();
            scwin.grd_StkOpt.hide();
        }
        await scwin.syncApp();
        setTimeout(async function(){ await scwin.syncIsuList() }, 500);
        await scwin.syncDoc();
        const parentFrameID = $c.util.getParameter($c.frame.srcUrl, "frameID");
        if (parentFrameID.indexOf('STF60000') !== -1) {
            scwin.btn_Acpt.hide();
            btn_Reject.hide();
            scwin.btn_NewList.hide();
            $c.util.getComponent('MaxTab_01').setSelectedIndex(5);
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07181.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.fr_MktId =scwin.getMktId(); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07181' }); }

try { scwin.vToday =$c.date.formatDate("yyyymmdd"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07181' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.grd_StkOpt = $c.util.getComponent('grd_StkOpt');
        scwin.chk_PREFSTK_TP_CD = $c.util.getComponent('chk_PREFSTK_TP_CD');
        scwin.panel_PREFSTK = $c.util.getComponent('panel_PREFSTK');
        scwin.btn_Acpt = $c.util.getComponent('btn_Acpt');
        scwin.btn_NewList = $c.util.getComponent('btn_NewList');
        scwin.panel_pharma_bio_com_yn = $c.util.getComponent('panel_pharma_bio_com_yn');
        scwin.pnl_LIST_INVSTG_COND = $c.util.getComponent('pnl_LIST_INVSTG_COND');
        scwin.pnl_MAJSHRHD_CONTN = $c.util.getComponent('pnl_MAJSHRHD_CONTN');
        scwin.grd_estiPrfm = $c.util.getComponent('grd_estiPrfm');
        scwin.grd_pipeProg = $c.util.getComponent('grd_pipeProg');
        scwin.grid_PubOfrList = $c.util.getComponent('grid_PubOfrList');
        scwin.grid_PriOfrList = $c.util.getComponent('grid_PriOfrList');
        scwin.grid_AssgnList = $c.util.getComponent('grid_AssgnList');
        scwin.grid_PriOfrAssgnList = $c.util.getComponent('grid_PriOfrAssgnList');
        scwin.dts_common_info = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsCommonInfo')) : $c.util.getComponent('dtsCommonInfo');
        scwin.dts_PubOfr = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_PubOfr')) : $c.util.getComponent('dts_PubOfr');
        scwin.dts_App = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_App')) : $c.util.getComponent('dts_App');
        scwin.dts_ShrsList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_ShrsList')) : $c.util.getComponent('dts_ShrsList');
        scwin.dts_LeadComList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_LeadComList')) : $c.util.getComponent('dts_LeadComList');
        scwin.dts_IsuList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_IsuList')) : $c.util.getComponent('dts_IsuList');
        scwin.dts_ApplDocList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_ApplDocList')) : $c.util.getComponent('dts_ApplDocList');
        scwin.dts_Isu = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Isu')) : $c.util.getComponent('dts_Isu');
        scwin.dts_NEWPREFSTK = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_NEWPREFSTK')) : $c.util.getComponent('dts_NEWPREFSTK');
        scwin.dts_PubOfrList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_PubOfrList')) : $c.util.getComponent('dts_PubOfrList');
        scwin.dts_AssgnList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_AssgnList')) : $c.util.getComponent('dts_AssgnList');
        scwin.dts_PrtDepoList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_PrtDepoList')) : $c.util.getComponent('dts_PrtDepoList');
        scwin.dts_PriOfrList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_PriOfrList')) : $c.util.getComponent('dts_PriOfrList');
        scwin.dts_PriOfrAssgnList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_PriOfrAssgnList')) : $c.util.getComponent('dts_PriOfrAssgnList');
        scwin.dts_StkOptDutyList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_StkOptDutyList')) : $c.util.getComponent('dts_StkOptDutyList');
        scwin.dts_estiPrfm = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsEstiPrfm')) : $c.util.getComponent('dtsEstiPrfm');
        scwin.dts_pipeProg = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsPipeProg')) : $c.util.getComponent('dtsPipeProg');
        scwin.fn_common_info = scwin.tx_script_dts_common_info;
        scwin.fn_setLeadCom = scwin.tx_script_dts_LeadComList;
        scwin.fn_sync_isuDtl = scwin.tx_script_dts_Isu;
        scwin.fn_trs = scwin.sbm_trs_Save;
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07181.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_close_onclick
 * @description btn_close 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_onclick = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        $c.win.closePopup();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07181.btn_close_onclick' }); }
};

/**
 * @method
 * @name dts_App_onloaderror
 * @description dts_App onloaderror 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dts_App_onloaderror = function () {
    try {
        $c.win.alert(scwin.dts_App);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07181.dts_App_onloaderror" });
    }
};

/**
 * @method
 * @name dts_App_onloadcompleted
 * @description dts_App onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_App_onloadcompleted = function (rowcount) {
    try {
        // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.fil.SetWindowPos2
        txt_label131.hide();
        ipt_txb_FS_ACNT_TP_NM.hide();
        txt_label132.hide();
        scwin.grd_estiPrfm.hide();
        scwin.grd_pipeProg.hide();
        if (scwin.dts_App.getCellData(1, "SPOT_ISU_TRD_MKT_TP") === '코스닥시장') {
            scwin.panel_pharma_bio_com_yn.show("");
            scwin.pnl_LIST_INVSTG_COND.show("");
            if ((scwin.dts_App.getCellData(1, "LIST_INVSTG_COND_TP_NM") === '기술성장기업 기술평가특례') || (scwin.dts_App.getCellData(1, "LIST_INVSTG_COND_TP_NM") === '기술성장기업 성장성추천')) {
                txt_label131.show("");
                ipt_txb_FS_ACNT_TP_NM.show("");
                scwin.grd_estiPrfm.show("");
            }
            if (scwin.dts_App.getCellData(1, "PHARMA_BIO_COM_YN") === 'Y') {
                txt_label132.show("");
                scwin.grd_pipeProg.show("");
            }
        } else {
            scwin.panel_pharma_bio_com_yn.hide();
            scwin.pnl_LIST_INVSTG_COND.hide();
            $c.fil.SetWindowPos2(scwin.pnl_MAJSHRHD_CONTN, 437, 486);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07181.dts_App_onloadcompleted" });
    }
};

/**
 * @method
 * @name dts_common_info_onloaderror
 * @description dts_common_info onloaderror 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dts_common_info_onloaderror = function () {
    try {
        $c.win.alert(scwin.dts_common_info);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07181.dts_common_info_onloaderror" });
    }
};

/**
 * @method
 * @name dts_ShrsList_onloadcompleted
 * @description dts_ShrsList onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ShrsList_onloadcompleted = function (rowcount) {
    try {
        void 0;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07181.dts_ShrsList_onloadcompleted" });
    }
};

/**
 * @method
 * @name dts_Isu_onloadcompleted
 * @description dts_Isu onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_onloadcompleted = function (rowcount) {
    try {
        if (scwin.dts_Isu.getCellData('1', "NPARVALSTK_YN") === 'Y') {
            ipt_edt_PARVAL.hide();
            ipt_edt_PER1STK_CAP.show("");
        } else {
            ipt_edt_PARVAL.show("");
            ipt_edt_PER1STK_CAP.hide();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07181.dts_Isu_onloadcompleted" });
    }
};

/**
 * @method
 * @name trs_Save_onfail
 * @description trs_Save onfail 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_onfail = async function () {
    try {
        await $c.fil.alertJobResult('F');
        $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07181.trs_Save_onfail" });
    }
};

/**
 * @method
 * @name trs_Save_onsuccess
 * @description btn_Acpt 을(를) 값을 넣는다 · btn_Reject 을(를) 값을 넣는다 외
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_onsuccess = async function () {
    try {
        scwin.btn_Acpt.setDisabled(true);
        scwin.btn_Acpt.setDisabled(true);
        $c.util.getComponent('btn_Reject').setSrc("../img/btn_reject_d.gif");
        $c.util.getComponent('btn_Reject').setDisabled(true);
        await $c.fil.alertJobResult('S1');
        scwin.parentRefresh();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07181.trs_Save_onsuccess" });
    }
};

/**
 * @method
 * @name grd_ApplDocList_ondblclick
 * @description grd_ApplDocList 더블클릭 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_ApplDocList_ondblclick = async function (row, colid) {
    try {
        if (scwin.dts_ApplDocList.getRowStatus(scwin.dts_ApplDocList.getRowPosition()) === 0) {
            if ("Y" === scwin.dts_ApplDocList.getCellData(row, "USE_YN")) {
                await scwin.filedown(scwin.dts_ApplDocList.getCellData(row, "ATTACH_FILE_SEQ"));
            }
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07181.grd_ApplDocList_ondblclick' }); }
};

/**
 * @method
 * @name btn_Acpt_onclick
 * @description btn_Acpt 의 onclick 에서 알림을 띄운다 외
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Acpt_onclick = async function () {
    try {
        const msg = "(※ 주의) 상장심사가 완료된 후 \n\n" + "즉시 '상장예비심사신청현황(STF07100)' 화면 등에 \n상장승인 여부를 입력해 주시기 바랍니다.";
        await $c.win.alert(msg);
        const vAnswer = await $c.win.confirm('접수처리 하시겠습니까?');
        if (vAnswer === true) {
            scwin.fn_trs("33");
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07181.btn_Acpt_onclick' }); }
};

/**
 * @method
 * @name btn_Reject_onclick
 * @description 「[없음]」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Reject_onclick = async function () {
    try {
        const vAnswer = await $c.win.confirm('반려처리 하시겠습니까?');
        if (vAnswer === true) {
            scwin.fn_trs("37");
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07181.btn_Reject_onclick' }); }
};

/**
 * @method
 * @name btn_NewList_onclick
 * @description btn_NewList 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_NewList_onclick = function () {
    try {
        scwin.openNewList();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07181.btn_NewList_onclick' }); }
};

/**
 * @method
 * @name dts_PubOfr_onloadcompleted
 * @description dts_PubOfr onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_PubOfr_onloadcompleted = function (rowcount) {
    try {
        if ("N" === scwin.dts_PubOfr.getCellData(1, "PUBOFR_YN")) {
            $c.util.getComponent("chk_chb_PUBOFR_YN").setValue(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07181.dts_PubOfr_onloadcompleted" });
    }
};

/**
 * @method
 * @name img_IsuNmGuide_onclick
 * @description img_IsuNmGuide 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_IsuNmGuide_onclick = function () {
    try {
        scwin.openDetailInputGuide();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07181.img_IsuNmGuide_onclick' }); }
};

/**
 * @method
 * @name img_IsuNmGuide1_onclick
 * @description img_IsuNmGuide1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_IsuNmGuide1_onclick = function () {
    try {
        scwin.openDetailInputGuide1();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07181.img_IsuNmGuide1_onclick' }); }
};

/**
 * @method
 * @name grd_IsuList_onclick
 * @description grd_IsuList 클릭 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_IsuList_onclick = function (row, colid) {
    try {
        if (row > 0) {
            scwin.setBzProcsNo(row);
        }
        scwin.fn_sync_isuDtl();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07181.grd_IsuList_onclick' }); }
};

/**
 * @method
 * @name dts_estiPrfm_onloadcompleted
 * @description dts_estiPrfm onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_estiPrfm_onloadcompleted = function (rowcount) {
    try {
        if (rowcount > 0) {
            const FS_ACNT_TP_NM = scwin.dts_estiPrfm.getCellData('1', "FS_ACNT_TP_NM");
            $c.util.getComponent("ipt_txb_FS_ACNT_TP_NM").setValue('(' + FS_ACNT_TP_NM + ')');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07181.dts_estiPrfm_onloadcompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_common_info
 * @description script dts common info 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_common_info = async function () {
    $c.util.getComponent("dma_scriptDtsCommonInfoReq").set("SCREN_ID", "ULDSTF07181.gfm");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, BZ_PROCS_NO"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, BZ_PROCS_NO", unresolved: "query_param:SCREN_PROCES_TP_CD,BZ_PROCS_NO" };
    const sbmOptions = {
        id: "tx_script_dts_common_info",
        method: "post",
        action: "/lstinvstg/LstInvstgCommon.do",
        ref: "dma_scriptDtsCommonInfoReq",
        target: "dtsCommonInfo=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_common_info_onloaderror'] === 'function') ? scwin['dts_common_info_onloaderror'] : (typeof scwin['dts_common_info_onfail'] === 'function') ? scwin['dts_common_info_onfail'] : undefined
    };
