/**
 * @method
 * @name setCheckboxData
 * @description set Checkbox Data 처리
 * @param {Object} obj 컴포넌트
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.setCheckboxData = function (obj, val) {
    if (val === 'Y') {
        obj.checked = true;
    } else {
        obj.checked = false;
    }
};

