 * @hidden N
 */
scwin.filedown = async function (attach_seq) {
    if ($c.session.getUserInfo("depCd") === '2500' || $c.session.getUserInfo("depCd") === '2520' || $c.session.getUserInfo("depCd") === '2540' || $c.session.getUserInfo("depCd") === '3300' || $c.session.getUserInfo("depCd") === '3320' || $c.session.getUserInfo("depCd") === '3330' || $c.session.getUserInfo("depCd") === '3350' || $c.session.getUserInfo("depCd") === '3E00' || $c.session.getUserInfo("depCd") === '3E10' || $c.session.getUserInfo("depCd") === '3E20' || $c.session.getUserInfo("depCd") === '3E30' || $c.session.getUserInfo("depCd") === '3E40' || $c.session.getUserInfo("depCd") === '2615' || $c.session.getUserInfo("depCd") === '3G20' || $c.session.getUserInfo("depCd") === '3E50') {
        await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /filedownload.do?attach_seq=). 전환 대상 화면이 확정되면 연결됩니다.') + attach_seq + "&gubun=25" + "&bzProcsNo=" + scwin.vBzProcsNo + "&fileTpCd=40&dtlTpCd=00";
    } else {
        await $c.win.alert('파일 열람권한이 없습니다');
    }
};

